INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Struktogramm nur für große Programme geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Abläufe hierarchisch darstellbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Struktogramm?', 3, '[{"text": "Hierarchische Programmstruktur zeigen", "correct": true, "because": "Top-Down-Darstellung"}, {"text": "Datenfluss visualisieren", "correct": false, "because": "Datenflussdiagramm-Thema"}, {"text": "Hardwareplanung", "correct": false, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Struktogramm?', 5, '[{"text": "Prozessblöcke", "correct": true, "because": "Zeigen Programmteile"}, {"text": "Entscheidungen", "correct": true, "because": "Steuern Verzweigungen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Komponenten", "correct": false, "because": "Komponentendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Struktogramme zeigen Top-Down-Abläufe. b) Sie ersetzen ERD-Diagramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ERD für Datenstruktur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Struktogramm?', 4, '[{"text": "Hierarchische Struktur", "correct": false, "because": "Kern des Diagramms"}, {"text": "Entscheidungspunkte", "correct": false, "because": "Steuern Ablauf"}, {"text": "UI-Design", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Struktogramm auch Schleifen darstellt?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederholungen hierarchisch möglich"}, {"text": "Nein", "correct": false, "because": "Schleifen enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für einen Prozessblock?', 3, '[{"text": "Rechteck", "correct": true, "because": "Standard für Prozessschritte"}, {"text": "Raute", "correct": false, "because": "Entscheidungen"}, {"text": "Pfeil", "correct": false, "because": "Nur Übergang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern ein Struktogramm?', 5, '[{"text": "Verzweigungen", "correct": true, "because": "Entscheidungen sichtbar"}, {"text": "Schleifen", "correct": true, "because": "Wiederholungen klar"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Struktogramme sind hierarchisch. b) Sie zeigen Hardwareplanung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Struktogramm?', 4, '[{"text": "Prozessblöcke", "correct": false, "because": "Grundlage der Struktur"}, {"text": "Entscheidungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Netzwerkknoten", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Struktogramm nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Abläufe"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen zeigt ein Struktogramm?', 4, '[{"text": "Schleifen", "correct": true, "because": "Wiederholungen darstellen"}, {"text": "Bedingungen", "correct": true, "because": "Entscheidungen zeigen"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Struktogramme überflüssig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hilfreich für Strukturübersicht"}, {"text": "Ja", "correct": false, "because": "Nützliches Werkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Struktogramm?', 3, '[{"text": "Hierarchische Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Schnelle Zeichnung", "correct": false, "because": "Qualität zählt"}, {"text": "Technische Details", "correct": false, "because": "Nicht im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Struktogramme zeigen Top-Down-Logik. b) Sie sind für Datenmodellierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenmodellierung ist ERM"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Struktogramm?', 5, '[{"text": "Ablaufübersicht", "correct": true, "because": "Klarheit über Hierarchie"}, {"text": "Strukturverständnis", "correct": true, "because": "Top-Down sichtbar"}, {"text": "Hardwareplanung", "correct": false, "because": "Verteilungsdiagramm"}, {"text": "Datenflussanalyse", "correct": false, "because": "Datenflussdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Struktogramm unwichtig?', 3, '[{"text": "Entscheidungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Hierarchie", "correct": false, "because": "Kern der Darstellung"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Struktogramm auch Datenflüsse?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Ablaufstruktur"}, {"text": "Ja", "correct": false, "because": "Datenflussdiagramm-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Struktogramme für Tests nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Testabläufe ableitbar"}, {"text": "Nein", "correct": false, "because": "Hilfreich für Testplanung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Schleife?', 4, '[{"text": "Rechteck mit Schleifenmarkierung", "correct": true, "because": "Standard für Wiederholungen"}, {"text": "Kreis", "correct": false, "because": "Andere Diagramme"}, {"text": "Pfeil", "correct": false, "because": "Nur Verbindung"}]');
